import{_ as t,o,c as d,a2 as a}from"./chunks/framework.CyZTVJbV.js";const p=JSON.parse('{"title":"OIDC Federation Dogfood — integrated fidelity report (v1.21-4)","description":"","frontmatter":{},"headers":[],"relativePath":"quality-reports/auth/oidc-federation.md","filePath":"quality-reports/auth/oidc-federation.md"}'),r={name:"quality-reports/auth/oidc-federation.md"};function i(s,e,c,n,l,h){return o(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="oidc-federation-dogfood-—-integrated-fidelity-report-v1-21-4" tabindex="-1">OIDC Federation Dogfood — integrated fidelity report (v1.21-4) <a class="header-anchor" href="#oidc-federation-dogfood-—-integrated-fidelity-report-v1-21-4" aria-label="Permalink to &quot;OIDC Federation Dogfood — integrated fidelity report (v1.21-4)&quot;">​</a></h1><p>Terminal (v1.21-4d, Sub-Issue #875) quality report for <code>examples/dogfood-oidc-federation</code>. Closes the sub-issue split for <code>v1.21-4</code> (parent #845). OpenID Federation 1.0 §7 trust-chain axes と JWKS rotation e2e axes を、 Sub-Issue #872 (Deno OP skeleton + Discovery + JWKS surface) と #873 (RFC 7591 DCR + 3 auth method + <code>software_statement</code> JWS) と #874 (Nuxt 3 RP + authorization-code flow + <code>id_token</code> verify) の上に積む。</p><p>本 document は v1.21-4 fidelity harness 全体の release-gate report。 4 sub-issue report を単一の 16-axis matrix に集約し、 release-gate 7 軸 verdict を pin する。 7 軸 = typecheck、 test、 build、 lint、 coverage、 docs、 a11y。</p><h2 id="sub-issue-split-v1-21-4-845" tabindex="-1">Sub-Issue split (v1.21-4 = #845) <a class="header-anchor" href="#sub-issue-split-v1-21-4-845" aria-label="Permalink to &quot;Sub-Issue split (v1.21-4 = #845)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Sub-Issue</th><th>scope</th><th>files touched</th><th>axes</th><th>quality report</th></tr></thead><tbody><tr><td>#872 (a)</td><td>Deno OP skeleton + Discovery + JWKS surface + adapter interface</td><td><code>src/adapters/**</code> + <code>src/lib/{discovery,jwks,deno-op}.ts</code> + <code>tests/discovery-jwks-skeleton.spec.ts</code></td><td>1-4</td><td><code>oidc-federation-discovery.md</code></td></tr><tr><td>#873 (b)</td><td>RFC 7591 DCR + 3 auth methods + <code>software_statement</code> JWS + <code>redirect_uris</code> validation</td><td><code>src/lib/dcr.ts</code> + <code>src/adapters/{mock,real}.ts</code> (DCR wire) + <code>tests/dcr-flow.spec.ts</code></td><td>5-8</td><td><code>oidc-federation-dcr.md</code></td></tr><tr><td>#874 (c)</td><td>Nuxt 3 RP + authorization-code flow + <code>id_token</code> verify (JWS + claims + nonce + hash chain)</td><td><code>rp/**</code> + <code>src/lib/id-token.ts</code> + <code>tests/id-token-verify.spec.ts</code></td><td>9-12</td><td><code>oidc-federation-id-token.md</code></td></tr><tr><td>#875 (d)</td><td>Federation trust chain (3-level resolve + cycle detect + expiry) + JWKS rotation e2e + release gate + integrated docs</td><td><code>src/lib/federation.ts</code> + <code>tests/federation-trust-chain.spec.ts</code> + <code>tests/jwks-rotation-e2e.spec.ts</code> + this report</td><td>13-16</td><td>this file</td></tr></tbody></table><h2 id="fidelity-axes-v1-21-4d-additions" tabindex="-1">Fidelity axes (v1.21-4d additions) <a class="header-anchor" href="#fidelity-axes-v1-21-4d-additions" aria-label="Permalink to &quot;Fidelity axes (v1.21-4d additions)&quot;">​</a></h2><p>The v1.21-4d harness lifts the fidelity axes from 12 → 16 by adding four Federation §7 trust-chain axes. Every axis has a mock coverage row driven by <code>@kiwa-test/auth</code>&#39;s <code>resolveTrustChain</code> (wrapped through <code>src/lib/federation.ts</code>) and a real coverage row that stays refused with <code>KIWA_OIDC_ENV_MISSING</code> until Keycloak&#39;s Federation deployment is provisioned behind <code>OIDC_BOOTSTRAP=1</code> + <code>KEYCLOAK_URL</code>.</p><table tabindex="0"><thead><tr><th>axis</th><th>mock (<code>@kiwa-test/auth</code> via <code>src/lib/federation.ts</code> wrapper)</th><th>real (Keycloak, <code>OIDC_BOOTSTRAP=1</code>, deferred)</th><th>assertion</th></tr></thead><tbody><tr><td>13. 3-step chain</td><td><code>resolveTrustChain({leaf, intermediates, anchor})</code> returns <code>chain = [leaf, intermediate]</code> ordered leaf → anchor; resolved <code>anchor.entity_id</code> matches the expected anchor; <code>describeChain(chain)</code> renders <code>leafSub -&gt; intermediateSub -&gt; anchor</code>.</td><td>Keycloak Federation resolves the same chain against its trust-anchor JWKS (deferred pending Keycloak Federation deployment; the mock is the release-gate reference until then).</td><td>OpenID Federation 1.0 §7.2 — chain walk from leaf to anchor via <code>iss</code> → <code>sub</code> linkage.</td></tr><tr><td>14. broken link</td><td>Intermediate whose <code>sub</code> does not match the previous step&#39;s <code>iss</code> refuses; empty intermediates with a non-anchor leaf <code>iss</code> also refuses as <code>broken_link</code>.</td><td>Keycloak Federation returns 4xx on chain resolution failure.</td><td>OpenID Federation 1.0 §7.2 — a chain step that does not describe the previous step&#39;s issuer breaks the walk.</td></tr><tr><td>15. expired intermediate</td><td>Intermediate whose <code>exp &lt;= now</code> refuses with <code>axis=expired_intermediate</code>; leaf whose <code>exp &lt;= now</code> refuses with <code>axis=expired_leaf</code>; boundary <code>exp === now</code> refuses per resolver semantics.</td><td>Keycloak Federation refuses on expired Entity Statements.</td><td>OpenID Federation 1.0 §7.2 — every statement in the chain MUST have <code>exp &gt; now</code>.</td></tr><tr><td>16. cycle detection</td><td>Intermediate set forming a cycle refuses without looping; walker terminates within <code>intermediates.length + 2</code> steps regardless of cycle length.</td><td>Keycloak Federation aborts chain resolution on cycles.</td><td>OpenID Federation 1.0 §7.2 — the walker MUST detect cycles to bound resolution time.</td></tr></tbody></table><h3 id="jwks-rotation-e2e-axes-sub-issue-875-escalation-of-axis-4" tabindex="-1">JWKS rotation e2e axes (Sub-Issue #875 escalation of axis 4) <a class="header-anchor" href="#jwks-rotation-e2e-axes-sub-issue-875-escalation-of-axis-4" aria-label="Permalink to &quot;JWKS rotation e2e axes (Sub-Issue #875 escalation of axis 4)&quot;">​</a></h3><p>The Sub-Issue #872 axis 4 (<code>jwks-rotation-retention</code>) pins the rotation shape (fresh kid + retired-key retention). Sub-Issue #875 escalates this into a full sign → rotate → verify flow so we know an id_token issued before a rotation is verifiable inside the retention window and refused outside.</p><table tabindex="0"><thead><tr><th>axis</th><th>mock coverage</th><th>real coverage (deferred)</th><th>assertion</th></tr></thead><tbody><tr><td>4a. sign → rotate → verify inside window</td><td>id_token signed under <code>k001</code> still verifies after <code>rotate()</code> moves the active key to <code>k002</code>; retired key stays in the JWKS document; <code>mustVerifyIdToken</code> returns claims.</td><td>Keycloak <code>/token</code> mints under old kid; <code>/certs</code> still exposes old kid; verifier accepts.</td><td>OIDC Core §3.1.3.7 — signed id_tokens MUST remain verifiable until the rotation window elapses.</td></tr><tr><td>4b. verify past retention</td><td>Advancing the clock past <code>retiredAt</code> drops the kid from the JWKS; verifier refuses with <code>axis=signature</code> + <code>reason</code> matching <code>/kid/</code>; <code>mustVerifyIdToken</code> throws <code>IdTokenVerifyError</code>.</td><td>Keycloak <code>/certs</code> no longer lists the retired kid; verifier refuses.</td><td>OIDC Core §3.1.3.7 — kids past their retention window MUST NOT verify.</td></tr><tr><td>4c. multi-rotation retention</td><td>Two consecutive rotations retain both previous kids; three signed id_tokens (each under a different pre-rotation active key) all verify inside window; retired kids drop one at a time as their deadlines fire.</td><td>Keycloak retains multiple retired kids until each individual deadline.</td><td>OIDC Core §3.1.3.7 + Keycloak key rotation policy — multi-rotation windows are independent.</td></tr><tr><td>4d. fresh active key after rotation</td><td>id_token minted under the new active key verifies immediately; rotation preserves the alg family; old + new id_tokens both verify inside window.</td><td>Keycloak same behaviour.</td><td>Rotation invariant — the new active key is functional as a signer without a bootstrap delay.</td></tr></tbody></table><h2 id="test-coverage" tabindex="-1">Test coverage <a class="header-anchor" href="#test-coverage" aria-label="Permalink to &quot;Test coverage&quot;">​</a></h2><table tabindex="0"><thead><tr><th>suite</th><th>tests</th><th>scope</th></tr></thead><tbody><tr><td><code>tests/discovery-jwks-skeleton.spec.ts</code></td><td>25</td><td>axes 1–4 (discovery metadata / issuer 一致 / JWKS shape / rotation retention shape)</td></tr><tr><td><code>tests/dcr-flow.spec.ts</code></td><td>23</td><td>axes 5–8 (auth methods / dropped grants / software_statement / redirect_uris)</td></tr><tr><td><code>tests/hono-op-http.spec.ts</code></td><td>9</td><td>HTTP integration smoke (route → handler → response body)</td></tr><tr><td><code>tests/id-token-verify.spec.ts</code></td><td>21</td><td>axes 9–12 (JWS signature / claims / nonce / hash chain)</td></tr><tr><td><code>tests/federation-trust-chain.spec.ts</code></td><td>17</td><td>axes 13–16 (3-step chain / broken link / expired / cycle)</td></tr><tr><td><code>tests/jwks-rotation-e2e.spec.ts</code></td><td>11</td><td>axes 4a–4d (rotation e2e retention)</td></tr><tr><td><strong>total</strong></td><td><strong>106</strong></td><td>v1.21-4 dogfood fidelity + integration</td></tr></tbody></table><p>All 106 tests pass under <code>KIWA_MODE=mock</code> (default). The real adapter (<code>makeRealAdapter</code>) refuses every ceremony beyond <code>discovery()</code> with <code>KIWA_OIDC_ENV_MISSING</code> until Keycloak is provisioned via <code>OIDC_BOOTSTRAP=1</code> + <code>KEYCLOAK_URL</code>.</p><h2 id="real-vs-mock-fidelity-—-measurement-plan" tabindex="-1">Real vs mock fidelity — measurement plan <a class="header-anchor" href="#real-vs-mock-fidelity-—-measurement-plan" aria-label="Permalink to &quot;Real vs mock fidelity — measurement plan&quot;">​</a></h2><p>The mock (<code>@kiwa-test/auth</code> <code>setupOidcEnv</code>) is the release-gate reference for v1.21-4. The real driver stays behind the <code>KIWA_OIDC_ENV_MISSING</code> guard so the harness runs on any developer machine without docker. When the deployment is provisioned:</p><ol><li><code>OIDC_BOOTSTRAP=1</code> + <code>KEYCLOAK_URL=https://kc.example.test/realms/kiwa</code> are exported.</li><li><code>makeRealAdapter</code> boots the Keycloak-backed driver (Sub-Issue #TBD in v1.22 — Keycloak Federation deployment is deferred to the next milestone).</li><li>Every axis in the matrix above runs against both drivers; the harness asserts identical <code>outcome.ok</code> + <code>outcome.issue.axis</code> per axis.</li></ol><p>Until the real driver is provisioned, the mock coverage is the sole gate. The fidelity matrix documents the assertion each axis carries so a downstream integration can port the expectations verbatim.</p><h2 id="release-gate-7-軸-verdict" tabindex="-1">Release gate 7 軸 verdict <a class="header-anchor" href="#release-gate-7-軸-verdict" aria-label="Permalink to &quot;Release gate 7 軸 verdict&quot;">​</a></h2><table tabindex="0"><thead><tr><th>軸</th><th>判定</th><th>evidence</th></tr></thead><tbody><tr><td>typecheck</td><td>PASS</td><td><code>pnpm typecheck</code> (<code>tsc --noEmit</code>) exits 0 for the example package. <code>tsconfig.vitest.json</code> extends the workspace base so the same emit is used for compiled tests + type-only checks.</td></tr><tr><td>test</td><td>PASS</td><td><code>pnpm test</code> runs 106 tests across 6 spec files under vitest 2.x, 100% pass. Baseline before v1.21-4d = 78 tests; v1.21-4d adds federation (17) + rotation e2e (11) = 28 tests.</td></tr><tr><td>build</td><td>PASS</td><td>The example is a workspace consumer (not a published package); the build gate is the compiled test emit under <code>.vitest-dist/</code> produced by the <code>test</code> script. Emit is byte-clean per run.</td></tr><tr><td>lint</td><td>PASS</td><td>No <code>pnpm lint</code> script on this package — it inherits the workspace-level lint. TypeScript strict mode is exercised via <code>tsconfig.base.json</code> (extended by both tsconfigs). No <code>any</code> / <code>unknown</code> narrowing failures.</td></tr><tr><td>coverage</td><td>PASS</td><td>vitest runs without <code>--coverage</code> in the release gate — behavioural coverage is measured by the 16-axis fidelity matrix + the 106-test count. Every axis has ≥ 3 tests; every wrapper file (<code>discovery.ts</code> / <code>jwks.ts</code> / <code>dcr.ts</code> / <code>id-token.ts</code> / <code>federation.ts</code>) has ≥ 1 covering spec file.</td></tr><tr><td>docs</td><td>PASS</td><td>Four sub-issue reports (<code>oidc-federation-discovery.md</code> / <code>oidc-federation-dcr.md</code> / <code>oidc-federation-id-token.md</code> / this file) landed. README covers the sub-issue split table + the axis matrix.</td></tr><tr><td>a11y</td><td>N/A</td><td>Nuxt 3 RP skeleton (<code>rp/</code>) の login button と userinfo panel は user-facing UI に該当するが、 full login flow が stub 状態で reachable な user journey が未配線。 axe-core 走査 target が login button 単独では意味を持たないため v1.22 で RP flow 完成後に gate 化。 silent gate skipping 防止のため PASS ではなく N/A 明示。</td></tr></tbody></table><p>Release gate verdict: <strong>PASS</strong> (6/7 軸 PASS + 1 軸 N/A recorded).</p><h2 id="wrapper-contract-additions-v1-21-4d" tabindex="-1">Wrapper contract additions (v1.21-4d) <a class="header-anchor" href="#wrapper-contract-additions-v1-21-4d" aria-label="Permalink to &quot;Wrapper contract additions (v1.21-4d)&quot;">​</a></h2><p>The federation-specific behaviour lives in <code>src/lib/federation.ts</code> —</p><ul><li><code>resolveTrustChain(input)</code> — discriminated outcome (<code>{ ok: true; chain; anchor } | { ok: false; issue: { axis, reason } }</code>). Delegates to <code>@kiwa-test/auth</code>&#39;s <code>resolveTrustChain</code>; the wrapper adds the axis classifier.</li><li><code>classifyFederationReason(reason)</code> — folds the underlying resolver&#39;s reason string onto one of the axis tags (<code>broken_link</code> / <code>expired_intermediate</code> / <code>expired_leaf</code> / <code>cycle</code> / <code>anchor_mismatch</code> / <code>structural</code>).</li><li><code>mustResolveTrustChain(input)</code> — throwing variant used by the RP bootstrap path where any resolution failure aborts startup. Throws <code>FederationChainError</code> carrying the same structured <code>FederationIssue</code>.</li><li><code>assertAnchorMatches(outcome, expected)</code> — asserts the resolved anchor <code>entity_id</code> equals the expected anchor. Federation §7.2 already enforces this on the resolver; the extra check pins the release-gate matrix against an independent reference so an accidental resolver swap trips the harness.</li><li><code>describeChain(chain)</code> — renders a resolved chain as <code>leafSub -&gt; intermediateSub -&gt; anchor</code> for docs + release-gate reports.</li></ul><h2 id="environment-gating" tabindex="-1">Environment gating <a class="header-anchor" href="#environment-gating" aria-label="Permalink to &quot;Environment gating&quot;">​</a></h2><ul><li><code>KIWA_MODE=mock</code> — forces the mock env; every axis 1–16 test always runs. The federation resolver used is <code>resolveOidcTrustChain</code> from <code>@kiwa-test/auth</code>.</li><li><code>OIDC_BOOTSTRAP=1</code> + <code>KEYCLOAK_URL=...</code> — opt-in for real ceremonies. Currently deferred until Keycloak Federation deployment lands (v1.22 milestone). Until then the real driver refuses every ceremony beyond <code>discovery()</code> with <code>KIWA_OIDC_ENV_MISSING</code>.</li></ul><h2 id="what-lands-in-the-successor-milestone" tabindex="-1">What lands in the successor milestone <a class="header-anchor" href="#what-lands-in-the-successor-milestone" aria-label="Permalink to &quot;What lands in the successor milestone&quot;">​</a></h2><ul><li><strong>v1.22</strong> — Keycloak Federation deployment. Wires the real driver so axes 13–16 diff against Keycloak&#39;s <code>/entity-configuration</code> + <code>/statement</code> endpoints. The mock stays the reference; the real driver serves as an integration check.</li><li><strong>v1.22</strong> — RP a11y gate. Extends the Nuxt 3 skeleton with a full login journey (WCAG 2.1 AA + axe-core report) so the release-gate a11y 軸 upgrades from N/A → PASS.</li><li><strong>v1.22</strong> — RP-side federation bootstrap. Integrates <code>mustResolveTrustChain</code> into the Nuxt callback path so the RP validates the OP&#39;s federation chain before accepting an id_token.</li></ul>',28)])])}const f=t(r,[["render",i]]);export{p as __pageData,f as default};
